insert into public.goals(id,name,description,sort) values (1,'חינוך מצוין ושוויון הזדמנויות','הרחבת ההישגים הלימודיים וצמצום פערים מגיל לידה ועד בגרות',1);
insert into public.goals(id,name,description,sort) values (2,'עיר נקייה, ירוקה ומטופחת','שיפור הניקיון, הגינון והמרחב הציבורי, והתייעלות אנרגטית',2);
insert into public.goals(id,name,description,sort) values (3,'שירות זמין ואיכותי לתושב','קיצור זמני מענה, הרחבת שירותים מקוונים ושקיפות',3);
insert into public.goals(id,name,description,sort) values (4,'צמיחה כלכלית והתחדשות עירונית','פיתוח אזורי תעסוקה, תכנון, רישוי והתחדשות שכונות',4);
insert into public.goals(id,name,description,sort) values (5,'קהילה חזקה, רווחה וביטחון אישי','חוסן קהילתי, מענה לאוכלוסיות במצבי סיכון ומוכנות לחירום',5);
insert into public.goals(id,name,description,sort) values (6,'ניהול עירוני יעיל, שקוף ואיתן','איתנות פיננסית, בקרה, ניהול הון אנושי ומערכות מידע',6);
