-- =====================================================================
-- קובץ 2 מתוך 2: נתוני הדגמה פיקטיביים - עיריית קרית גת
-- המבנה הארגוני נלקח מאתר העירייה; כל הסכומים והמשימות בדויים
-- =====================================================================
-- ניתן להריץ שוב כדי לאפס את נתוני ההדגמה; משתמשים והרשאות נשמרים
delete from public.tasks;
delete from public.budget_items;
update public.profiles set division_id = null, department_id = null;
delete from public.departments;
delete from public.divisions;
delete from public.goals;
delete from public.quarters;
delete from public.audit_log;
select setval('public.tasks_id_seq', 1, false);

select setval('public.goals_id_seq', (select max(id) from public.goals));
select setval('public.divisions_id_seq', (select max(id) from public.divisions));
select setval('public.departments_id_seq', (select max(id) from public.departments));
select setval('public.budget_items_id_seq', (select max(id) from public.budget_items));
select setval('public.tasks_id_seq', (select max(id) from public.tasks));
